import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { Activity, AlertTriangle, Archive, ArrowDownToLine, ArrowRight, BarChart3, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight, Circle, ClipboardCheck, Clock3, Download, FileArchive, FileSpreadsheet, FileText, Flag, FolderKanban, ListTodo, Paperclip, Plus, RefreshCw, Send, Target, Upload, Users, X } from 'lucide-react'
import { apiFetch, apiJson, jsonRequest, type AuthUser } from './api'
import { requestWorkspace } from './data'
import type { EventScoreLine, Project, ProjectEvent, ProjectEventReview, ProjectMilestone, ProjectPhase, ProjectReport, ProjectTemplate, Task, WorkspaceData } from './types'
import './project-workbench.css'

type TabId = 'overview' | 'plan' | 'gantt' | 'events' | 'reports' | 'files'
type ProjectFile = { id: string; name: string; size: number; mimeType: string; uploadedBy: string; createdAt: string }
type UserOption = Pick<AuthUser, 'id' | 'displayName' | 'email' | 'role' | 'disabled'>
type GanttItem = { id: string; title: string; kind: 'phase' | 'task' | 'milestone' | 'event'; startDate: string; endDate: string; status: string; progress: number; detail: string }
const today = () => { const d = new Date(); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10) }
const addDays = (base: string, days: number) => { const d = new Date(`${base}T12:00:00`); d.setDate(d.getDate() + days); return d.toISOString().slice(0,10) }
const dateLabel = (value?: string) => value ? new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(`${value}T12:00:00`)) : '—'
const monthLabel = () => today().slice(0,7)
const dayNumber = (value?: string) => { if (!value) return null; const [year, month, day] = value.slice(0,10).split('-').map(Number); return year && month && day ? Math.floor(Date.UTC(year, month - 1, day) / 86_400_000) : null }
const dayString = (value: number) => new Date(value * 86_400_000).toISOString().slice(0,10)
const axisDateLabel = (value: number) => new Intl.DateTimeFormat('zh-CN', { month: 'numeric', day: 'numeric', timeZone: 'UTC' }).format(new Date(value * 86_400_000))
const fileSize = (bytes: number) => bytes < 1024 * 1024 ? `${Math.max(1,Math.round(bytes/1024))} KB` : `${(bytes/1024/1024).toFixed(1)} MB`
const statusLabel: Record<string, string> = { draft: '草稿', active: '进行中', 'on-hold': '已暂停', completed: '已完成', cancelled: '已取消', 'not-started': '未开始', 'in-progress': '进行中', blocked: '受阻', planned: '计划中', missed: '已错过', open: '待处理', 'self-review': '待自评', 'manager-review': '待主管评审', approved: '已完成评审', todo: '待办', done: '已完成' }
const eventLabel: Record<string, string> = { meeting: '会议', decision: '决策', risk: '风险', issue: '问题', change: '变更', deliverable: '交付物', other: '其他' }
const priorityLabel: Record<string, string> = { high: '高', medium: '中', low: '低' }

function WorkModal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  useEffect(() => { const key = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key) }, [onClose])
  return <motion.div className="pw-modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={e => e.target === e.currentTarget && onClose()}><motion.section className={`pw-modal ${wide ? 'pw-modal-wide' : ''}`} initial={{ opacity: 0, y: 14, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10 }}><div className="pw-modal-head"><div><span>PROJECT WORKSPACE</span><h2>{title}</h2></div><button type="button" aria-label="关闭" className="pw-icon-button" onClick={onClose}><X size={18}/></button></div>{children}</motion.section></motion.div>
}

function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) {
  return <div className="pw-empty"><span><FolderKanban size={22}/></span><b>{title}</b><p>{detail}</p>{action}</div>
}

function Field({ label, children, wide = false }: { label: string; children: ReactNode; wide?: boolean }) { return <label className={`pw-field ${wide ? 'pw-field-wide' : ''}`}><span>{label}</span>{children}</label> }

export default function ProjectWorkbench({ workspace, currentUser, onChange, onToast, selectedProjectId, onProjectSelected, onCreateProject, onEditProject }: {
  workspace: WorkspaceData; currentUser: AuthUser; onChange: (next: WorkspaceData) => void; onToast: (message: string) => void
  selectedProjectId: string | null; onProjectSelected: (id: string | null) => void; onCreateProject: () => void; onEditProject: () => void
}) {
  const [tab, setTab] = useState<TabId>('overview')
  const [modal, setModal] = useState<'template' | 'phase' | 'milestone' | 'task' | 'event' | 'report' | 'self-review' | 'manager-review' | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [templates, setTemplates] = useState<ProjectTemplate[]>([])
  const [users, setUsers] = useState<UserOption[]>([])
  const [files, setFiles] = useState<ProjectFile[]>([])
  const [fileBusy, setFileBusy] = useState(false)
  const [reviewId, setReviewId] = useState('')
  const [templateId, setTemplateId] = useState('tpl-product-development')
  const [importInputKey, setImportInputKey] = useState(0)

  const projects = workspace.projects
  const selectedProject = projects.find(project => project.id === selectedProjectId) ?? projects[0]
  const canManage = currentUser.role === 'admin' || currentUser.role === 'plm_manager'
  const projectId = selectedProject?.id ?? ''
  const projectTasks = useMemo(() => workspace.tasks.filter(task => task.projectId === projectId).sort((a,b) => (a.wbsCode ?? '').localeCompare(b.wbsCode ?? '') || a.dueDate.localeCompare(b.dueDate)), [workspace.tasks, projectId])
  const phases = useMemo(() => workspace.projectPhases.filter(phase => phase.projectId === projectId).sort((a,b) => a.order-b.order), [workspace.projectPhases, projectId])
  const milestones = useMemo(() => workspace.projectMilestones.filter(item => item.projectId === projectId).sort((a,b) => a.dueDate.localeCompare(b.dueDate)), [workspace.projectMilestones, projectId])
  const events = useMemo(() => workspace.projectEvents.filter(item => item.projectId === projectId).sort((a,b) => b.createdAt.localeCompare(a.createdAt)), [workspace.projectEvents, projectId])
  const ganttItems = useMemo<GanttItem[]>(() => {
    const items: GanttItem[] = [
      ...phases.map(item => ({ id: `phase-${item.id}`, title: `${item.code} · ${item.name}`, kind: 'phase' as const, startDate: item.startDate, endDate: item.dueDate, status: item.status, progress: Number(item.progress ?? 0), detail: `阶段 · ${item.owner || '未指派'}` })),
      ...projectTasks.map(item => ({ id: `task-${item.id}`, title: `${item.wbsCode ? `${item.wbsCode} · ` : ''}${item.title}`, kind: 'task' as const, startDate: item.startDate || item.dueDate, endDate: item.dueDate, status: item.status, progress: item.status === 'done' ? 100 : Number(item.progress ?? 0), detail: `任务 · ${item.assignee || '未指派'}` })),
      ...milestones.map(item => ({ id: `milestone-${item.id}`, title: `${item.code} · ${item.title}`, kind: 'milestone' as const, startDate: item.dueDate, endDate: item.dueDate, status: item.status, progress: item.status === 'completed' ? 100 : 0, detail: '里程碑' })),
      ...events.map(item => ({ id: `event-${item.id}`, title: `${item.code} · ${item.title}`, kind: 'event' as const, startDate: item.startDate || item.dueDate, endDate: item.dueDate, status: item.status, progress: item.status === 'completed' ? 100 : 0, detail: `事件 · ${item.owner || '未指派'}` })),
    ]
    return items.filter(item => dayNumber(item.startDate) !== null && dayNumber(item.endDate) !== null).sort((a,b) => (dayNumber(a.startDate) ?? 0) - (dayNumber(b.startDate) ?? 0) || ['phase','task','milestone','event'].indexOf(a.kind) - ['phase','task','milestone','event'].indexOf(b.kind))
  }, [phases, projectTasks, milestones, events])
  const ganttTimeline = useMemo(() => {
    const dates = [selectedProject?.startDate, selectedProject?.dueDate, ...ganttItems.flatMap(item => [item.startDate, item.endDate])].map(dayNumber).filter((value): value is number => value !== null)
    const earliest = dates.length ? Math.min(...dates) : (dayNumber(today()) ?? 0)
    const latest = dates.length ? Math.max(...dates) : earliest + 6
    const startDay = earliest - ((new Date(earliest * 86_400_000).getUTCDay() + 6) % 7)
    const endDayRaw = Math.max(latest, startDay + 6)
    const endDay = endDayRaw + (6 - ((new Date(endDayRaw * 86_400_000).getUTCDay() + 6) % 7))
    const weekCount = Math.max(1, Math.ceil((endDay - startDay + 1) / 7))
    return { startDay, endDay, dayCount: endDay - startDay + 1, weekCount, weeks: Array.from({ length: weekCount }, (_, index) => startDay + index * 7) }
  }, [selectedProject?.startDate, selectedProject?.dueDate, ganttItems])
  const reports = useMemo(() => workspace.projectReports.filter(item => item.projectId === projectId).sort((a,b) => b.period.localeCompare(a.period) || (b.createdAt ?? '').localeCompare(a.createdAt ?? '')), [workspace.projectReports, projectId])
  const eventReviews = useMemo(() => workspace.projectEventReviews.filter(item => item.projectId === projectId), [workspace.projectEventReviews, projectId])
  const completion = projectTasks.length ? Math.round(projectTasks.reduce((sum, task) => sum + (task.status === 'done' ? 100 : Number(task.progress ?? 0)), 0) / projectTasks.length) : Math.round(Number(selectedProject?.progress ?? 0))
  const nextMilestones = milestones.filter(item => item.status === 'planned').length
  const overdueTasks = projectTasks.filter(task => task.status !== 'done' && task.dueDate < today()).length
  const currentReview = eventReviews.find(review => review.id === reviewId) ?? eventReviews.find(review => review.status === 'self-review' || review.status === 'manager-review')

  const refresh = async () => { const next = await requestWorkspace(); onChange(next) }
  const run = async (action: () => Promise<unknown>, message: string) => {
    if (busy) return
    setBusy(true); setError('')
    try { await action(); await refresh(); onToast(message); setModal(null) }
    catch (value) { const msg = value instanceof Error ? value.message : '操作失败，请稍后重试。'; setError(msg); onToast(msg) }
    finally { setBusy(false) }
  }
  useEffect(() => { if (!selectedProjectId && projects[0]) onProjectSelected(projects[0].id) }, [selectedProjectId, projects, onProjectSelected])
  useEffect(() => {
    void apiJson<ProjectTemplate[]>('/api/project-template-library').then(setTemplates).catch(() => setTemplates([]))
    void apiJson<{ users: UserOption[] }>('/api/auth/users').then(result => setUsers((result.users ?? []).filter(user => !user.disabled))).catch(() => setUsers([]))
  }, [])
  useEffect(() => {
    if (!projectId) { setFiles([]); return }
    void apiJson<ProjectFile[]>(`/api/projects/${encodeURIComponent(projectId)}/files`).then(setFiles).catch(() => setFiles([]))
  }, [projectId])

  const createFromTemplate = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const fd = new FormData(event.currentTarget)
    await run(async () => {
      const result = await apiJson<{ project: Project }>('/api/projects/from-template', jsonRequest('POST', { templateId: String(fd.get('templateId') ?? ''), name: String(fd.get('name') ?? ''), description: String(fd.get('description') ?? ''), type: String(fd.get('type') ?? ''), department: String(fd.get('department') ?? ''), owner: String(fd.get('owner') ?? currentUser.displayName), ownerId: String(fd.get('ownerId') ?? currentUser.id), sponsor: String(fd.get('sponsor') ?? ''), startDate: String(fd.get('startDate') ?? today()), dueDate: String(fd.get('dueDate') ?? ''), priority: String(fd.get('priority') ?? 'medium'), goal: String(fd.get('goal') ?? ''), scope: String(fd.get('scope') ?? ''), successCriteria: String(fd.get('successCriteria') ?? '') }))
      onProjectSelected(result.project.id)
    }, '项目与阶段计划已创建')
  }
  const createPhase = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedProject) return; const fd = new FormData(event.currentTarget); const id = crypto.randomUUID()
    await run(() => apiJson('/api/project-phases', jsonRequest('POST', { id, projectId, code: String(fd.get('code') ?? `P${phases.length+1}`), name: String(fd.get('name') ?? ''), order: phases.length+1, startDate: String(fd.get('startDate') ?? today()), dueDate: String(fd.get('dueDate') ?? today()), owner: String(fd.get('owner') ?? selectedProject.owner ?? currentUser.displayName), status: 'not-started', progress: 0, deliverables: String(fd.get('deliverables') ?? ''), acceptanceCriteria: String(fd.get('acceptanceCriteria') ?? '') })), '项目阶段已新增')
  }
  const createMilestone = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedProject) return; const fd = new FormData(event.currentTarget); const id = crypto.randomUUID()
    await run(() => apiJson('/api/project-milestones', jsonRequest('POST', { id, projectId, phaseId: String(fd.get('phaseId') ?? '') || undefined, code: String(fd.get('code') ?? `M${milestones.length+1}`), title: String(fd.get('title') ?? ''), dueDate: String(fd.get('dueDate') ?? today()), owner: String(fd.get('owner') ?? selectedProject.owner ?? currentUser.displayName), status: 'planned', acceptanceCriteria: String(fd.get('acceptanceCriteria') ?? '') })), '项目里程碑已新增')
  }
  const createTask = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedProject) return; const fd = new FormData(event.currentTarget)
    await run(() => apiJson('/api/tasks', jsonRequest('POST', { title: String(fd.get('title') ?? ''), description: String(fd.get('description') ?? ''), projectId, phaseId: String(fd.get('phaseId') ?? '') || undefined, milestoneId: String(fd.get('milestoneId') ?? '') || undefined, wbsCode: String(fd.get('wbsCode') ?? ''), startDate: String(fd.get('startDate') ?? today()), dueDate: String(fd.get('dueDate') ?? today()), priority: String(fd.get('priority') ?? 'medium'), status: 'todo', assignee: String(fd.get('assignee') ?? currentUser.displayName), assigneeId: String(fd.get('assigneeId') ?? currentUser.id), estimateHours: Number(fd.get('estimateHours') ?? 0), progress: 0, acceptanceCriteria: String(fd.get('acceptanceCriteria') ?? '') })), '项目任务已创建')
  }
  const createEvent = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedProject) return; const fd = new FormData(event.currentTarget)
    await run(() => apiJson('/api/project-events', jsonRequest('POST', { id: crypto.randomUUID(), projectId, phaseId: String(fd.get('phaseId') ?? '') || undefined, milestoneId: String(fd.get('milestoneId') ?? '') || undefined, taskId: String(fd.get('taskId') ?? '') || undefined, code: String(fd.get('code') ?? `EVT-${String(events.length+1).padStart(3,'0')}`), type: String(fd.get('type') ?? 'deliverable'), title: String(fd.get('title') ?? ''), description: String(fd.get('description') ?? ''), owner: String(fd.get('owner') ?? currentUser.displayName), ownerId: String(fd.get('ownerId') ?? currentUser.id), department: String(fd.get('department') ?? selectedProject.department ?? ''), startDate: String(fd.get('startDate') ?? today()), dueDate: String(fd.get('dueDate') ?? today()), status: 'open', projectWeight: Number(fd.get('projectWeight') ?? 0) })), '项目事件已记录')
  }
  const createReport = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedProject) return; const fd = new FormData(event.currentTarget)
    await run(() => apiJson('/api/project-reports', jsonRequest('POST', { id: crypto.randomUUID(), projectId, period: String(fd.get('period') ?? monthLabel()), progress: Number(fd.get('progress') ?? completion), achievements: String(fd.get('achievements') ?? ''), blockers: String(fd.get('blockers') ?? ''), risks: String(fd.get('risks') ?? ''), decisionsNeeded: String(fd.get('decisionsNeeded') ?? ''), nextSteps: String(fd.get('nextSteps') ?? '') })), '项目报告已保存')
  }
  const updatePhase = (phase: ProjectPhase, completed: boolean) => run(() => apiJson(`/api/project-phases/${encodeURIComponent(phase.id)}`, jsonRequest('PATCH', { status: completed ? 'completed' : 'in-progress', progress: completed ? 100 : Math.max(phase.progress, 1), ...(completed ? { actualEndDate: today() } : {}) })), completed ? '阶段已完成' : '阶段已启动')
  const updateMilestone = (milestone: ProjectMilestone) => run(() => apiJson(`/api/project-milestones/${encodeURIComponent(milestone.id)}`, jsonRequest('PATCH', { status: milestone.status === 'completed' ? 'planned' : 'completed', actualDate: milestone.status === 'completed' ? '' : today() })), milestone.status === 'completed' ? '里程碑已重新打开' : '里程碑已验收')
  const toggleTask = (task: Task) => run(() => apiJson(`/api/tasks/${encodeURIComponent(task.id)}`, jsonRequest('PATCH', { status: task.status === 'done' ? 'todo' : 'done', progress: task.status === 'done' ? 0 : 100 })), task.status === 'done' ? '任务已重新打开' : '任务已完成')
  const completeEvent = (item: ProjectEvent) => run(() => apiJson(`/api/project-events/${encodeURIComponent(item.id)}`, jsonRequest('PATCH', { status: item.status === 'completed' ? 'in-progress' : 'completed', actualDate: item.status === 'completed' ? '' : today() })), item.status === 'completed' ? '事件已重新打开' : '事件已标记完成')
  const startReview = (item: ProjectEvent) => run(async () => {
    const review = await apiJson<ProjectEventReview>(`/api/project-events/${encodeURIComponent(item.id)}/start-review`, jsonRequest('POST', { reviewer: currentUser.displayName, period: monthLabel() }))
    setReviewId(review.id)
  }, '已发起事件绩效评审')
  const submitSelfReview = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!currentReview) return; const fd = new FormData(event.currentTarget)
    const scores = currentReview.rulesSnapshot.map(rule => ({ kpiRuleId: rule.kpiRuleId, actual: Number(fd.get(`actual-${rule.kpiRuleId}`)), comment: String(fd.get(`comment-${rule.kpiRuleId}`) ?? '') }))
    await run(() => apiJson(`/api/project-event-reviews/${encodeURIComponent(currentReview.id)}/self`, jsonRequest('PATCH', { scores, comment: String(fd.get('comment') ?? '') })), '自评已提交，进入主管评审')
  }
  const submitManagerReview = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!currentReview) return; const fd = new FormData(event.currentTarget)
    const selfLines = currentReview.selfScores ?? []
    const scores = currentReview.rulesSnapshot.map(rule => {
      const own = selfLines.find(line => line.kpiRuleId === rule.kpiRuleId)
      return { kpiRuleId: rule.kpiRuleId, actual: Number(fd.get(`actual-${rule.kpiRuleId}`) ?? own?.actual ?? 0), score: Number(fd.get(`score-${rule.kpiRuleId}`) ?? own?.score ?? 0), comment: String(fd.get(`comment-${rule.kpiRuleId}`) ?? '') }
    })
    await run(() => apiJson(`/api/project-event-reviews/${encodeURIComponent(currentReview.id)}/manager`, jsonRequest('PATCH', { scores, comment: String(fd.get('comment') ?? '') })), '主管评审已完成')
  }

  const download = async (path: string, filename: string) => {
    try {
      const response = await apiFetch(path)
      if (!response.ok) throw new Error(await response.text() || `下载失败（HTTP ${response.status}）`)
      const blob = await response.blob(), url = URL.createObjectURL(blob), link = document.createElement('a')
      link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); onToast('文件已开始下载')
    } catch (value) { onToast(value instanceof Error ? value.message : '下载失败') }
  }
  const uploadProjectFile = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!projectId) return; const form = event.currentTarget, fd = new FormData(form)
    setFileBusy(true); setError('')
    try {
      const response = await apiFetch(`/api/projects/${encodeURIComponent(projectId)}/files`, { method: 'POST', body: fd })
      const body = await response.json().catch(() => ({})) as { error?: string; message?: string }
      if (!response.ok) throw new Error(body.message ?? body.error ?? `上传失败（HTTP ${response.status}）`)
      setFiles(await apiJson<ProjectFile[]>(`/api/projects/${encodeURIComponent(projectId)}/files`)); form.reset(); onToast('项目附件已上传')
    } catch (value) { const msg = value instanceof Error ? value.message : '上传失败'; setError(msg); onToast(msg) }
    finally { setFileBusy(false) }
  }
  const importPlan = async (file?: File) => {
    if (!file || !projectId) return
    setFileBusy(true); setError('')
    try {
      const fd = new FormData(); fd.set('file', file)
      const response = await apiFetch(`/api/projects/${encodeURIComponent(projectId)}/import-plan`, { method: 'POST', body: fd })
      const body = await response.json().catch(() => ({})) as { error?: string; message?: string; counts?: { tasks?: number; phases?: number; milestones?: number } }
      if (!response.ok) throw new Error(body.message ?? body.error ?? `导入失败（HTTP ${response.status}）`)
      await refresh(); onToast(`导入完成：${body.counts?.phases ?? 0} 个阶段，${body.counts?.milestones ?? 0} 个里程碑，${body.counts?.tasks ?? 0} 条任务`)
    } catch (value) { const msg = value instanceof Error ? value.message : '导入失败'; setError(msg); onToast(msg) }
    finally { setFileBusy(false); setImportInputKey(value => value+1) }
  }
  const refreshFiles = async () => { if (!projectId) return; setFiles(await apiJson<ProjectFile[]>(`/api/projects/${encodeURIComponent(projectId)}/files`)) }
  const tabs: { id: TabId; label: string; icon: typeof Target }[] = [
    { id: 'overview', label: '项目概览', icon: Target }, { id: 'plan', label: '阶段与任务', icon: ListTodo }, { id: 'gantt', label: '甘特图', icon: CalendarDays }, { id: 'events', label: '项目事件与绩效', icon: ClipboardCheck }, { id: 'reports', label: '项目汇报', icon: BarChart3 }, { id: 'files', label: '图文档与归档', icon: Paperclip },
  ]

  return <section className="pw-shell">
    <div className="pw-toolbar"><div><div className="pw-eyebrow">PROJECT DELIVERY SYSTEM</div><h2>项目全生命周期工作台</h2><p>立项、阶段门、任务分解、里程碑、事件绩效与交付物统一追踪。</p></div><div className="pw-toolbar-actions"><button className="pw-button pw-button-secondary" onClick={() => { void refresh().catch(value => onToast(value instanceof Error ? value.message : '刷新失败')) }} disabled={busy}><RefreshCw size={15}/>刷新数据</button>{canManage && <button className="pw-button pw-button-primary" onClick={() => setModal('template')}><Plus size={15}/>模板建项</button>}<button className="pw-button pw-button-primary" onClick={onCreateProject}><Plus size={15}/>新建项目</button></div></div>
    <div className="pw-metrics"><div><span><FolderKanban size={16}/>项目总数</span><b>{projects.length}</b><small>当前账套</small></div><div><span><Activity size={16}/>项目进度</span><b>{selectedProject ? `${completion}%` : '—'}</b><small>{selectedProject?.name ?? '尚未选择项目'}</small></div><div><span><Flag size={16}/>待验收里程碑</span><b>{nextMilestones}</b><small>当前项目</small></div><div><span><AlertTriangle size={16}/>逾期任务</span><b className={overdueTasks ? 'pw-danger' : ''}>{overdueTasks}</b><small>按计划截止日期</small></div></div>
    <div className="pw-project-select"><div className="pw-select-wrap"><FolderKanban size={16}/><select aria-label="当前项目" value={selectedProject?.id ?? ''} onChange={event => onProjectSelected(event.target.value || null)}><option value="">选择一个项目</option>{projects.map(project => <option key={project.id} value={project.id}>{project.code ? `${project.code} · ` : ''}{project.name}</option>)}</select><ChevronDown size={15}/></div>{selectedProject && <div className="pw-project-status"><span className={`pw-status status-${selectedProject.status ?? 'active'}`}>{statusLabel[selectedProject.status ?? 'active']}</span><span>负责人：{selectedProject.owner || currentUser.displayName}</span><span>计划：{dateLabel(selectedProject.startDate)} — {dateLabel(selectedProject.dueDate)}</span><button type="button" className="pw-link-button" onClick={onEditProject}>编辑基本信息</button></div>}</div>
    <nav className="pw-tabs" aria-label="项目工作台模块">{tabs.map(item => <button key={item.id} className={tab === item.id ? 'is-active' : ''} onClick={() => setTab(item.id)}><item.icon size={16}/>{item.label}{item.id === 'events' && events.length > 0 && <i>{events.length}</i>}</button>)}</nav>
    {!selectedProject ? <Empty title="当前工作区还没有项目" detail="先创建一个项目，或选择模板快速生成阶段、里程碑和任务。" action={canManage && <button className="pw-button pw-button-primary" onClick={() => setModal('template')}><Plus size={15}/>从项目模板创建</button>}/> : <>
      {tab === 'overview' && <div className="pw-content-grid">
        <section className="pw-panel pw-project-summary"><div className="pw-panel-heading"><div><span>PROJECT CHARTER</span><h3>{selectedProject.name}</h3></div><span className={`pw-status status-${selectedProject.status ?? 'active'}`}>{statusLabel[selectedProject.status ?? 'active']}</span></div><p className="pw-summary-text">{selectedProject.description || '尚未填写项目简介。'}</p><div className="pw-summary-grid"><div><small>项目编号</small><b>{selectedProject.code ?? '—'}</b></div><div><small>项目类型</small><b>{selectedProject.type ?? '通用项目'}</b></div><div><small>所属部门</small><b>{selectedProject.department || '—'}</b></div><div><small>项目负责人</small><b>{selectedProject.owner || currentUser.displayName}</b></div><div><small>发起/赞助人</small><b>{selectedProject.sponsor || '—'}</b></div><div><small>当前阶段</small><b>{selectedProject.stage || phases.find(phase => phase.status === 'in-progress')?.name || '—'}</b></div></div><div className="pw-progress-block"><div><span>综合进度</span><b>{completion}%</b></div><div className="pw-progress-track"><i style={{ width: `${completion}%` }}/></div><small>{projectTasks.filter(task => task.status === 'done').length} / {projectTasks.length} 项任务完成</small></div><div className="pw-charter-fields"><div><small>项目目标</small><p>{selectedProject.goal || '未填写'}</p></div><div><small>范围边界</small><p>{selectedProject.scope || '未填写'}</p></div><div><small>成功标准</small><p>{selectedProject.successCriteria || '未填写'}</p></div></div></section>
        <aside className="pw-side-stack"><section className="pw-panel"><div className="pw-panel-heading"><div><span>UPCOMING</span><h3>近期里程碑</h3></div><button className="pw-icon-button" onClick={() => setTab('plan')} aria-label="查看计划"><ArrowRight size={16}/></button></div>{milestones.filter(item => item.status === 'planned').slice(0,4).map(item => <div className="pw-mini-row" key={item.id}><i className="pw-milestone-dot"/><div><b>{item.title}</b><small>{dateLabel(item.dueDate)} · {item.owner}</small></div><span className={item.dueDate < today() ? 'pw-danger' : ''}>{item.dueDate < today() ? '逾期' : '计划'}</span></div>)}{!milestones.length && <p className="pw-muted">尚无里程碑，建议先把重要验收点列出来。</p>}</section><section className="pw-panel"><div className="pw-panel-heading"><div><span>FOCUS</span><h3>本项目行动</h3></div><ListTodo size={16}/></div><div className="pw-statline"><span>未完成任务</span><b>{projectTasks.filter(task => task.status !== 'done').length}</b></div><div className="pw-statline"><span>开放事件</span><b>{events.filter(item => !['completed','cancelled'].includes(item.status)).length}</b></div><div className="pw-statline"><span>待主管评审</span><b>{eventReviews.filter(review => review.status === 'manager-review').length}</b></div></section></aside>
        <section className="pw-panel pw-phase-preview"><div className="pw-panel-heading"><div><span>PHASE GATES</span><h3>阶段门进展</h3></div><button className="pw-link-button" onClick={() => setTab('plan')}>管理阶段<ArrowRight size={14}/></button></div>{phases.length ? phases.map(phase => <div className="pw-phase-line" key={phase.id}><div className="pw-phase-number">{phase.order}</div><div className="pw-phase-body"><div><b>{phase.name}</b><span className={`pw-status status-${phase.status}`}>{statusLabel[phase.status]}</span></div><small>{dateLabel(phase.startDate)} — {dateLabel(phase.dueDate)} · {phase.owner}</small><div className="pw-progress-track"><i style={{ width: `${phase.progress}%` }}/></div></div><strong>{phase.progress}%</strong></div>) : <p className="pw-muted">无阶段计划。选择“模板建项”可自动生成阶段、验收点与任务。</p>}</section>
      </div>}

      {tab === 'plan' && <div className="pw-plan-layout"><section className="pw-panel"><div className="pw-panel-heading"><div><span>WORK BREAKDOWN STRUCTURE</span><h3>阶段与里程碑</h3></div><div className="pw-panel-actions">{canManage && <button className="pw-button pw-button-secondary" onClick={() => setModal('milestone')}><Plus size={14}/>新增里程碑</button>}{canManage && <button className="pw-button pw-button-primary" onClick={() => setModal('phase')}><Plus size={14}/>新增阶段</button>}</div></div>{phases.length ? <div className="pw-phase-list">{phases.map(phase => <article className="pw-phase-card" key={phase.id}><div className="pw-phase-head"><div className="pw-phase-number">{phase.order}</div><div className="pw-phase-name"><b>{phase.code} · {phase.name}</b><span>{dateLabel(phase.startDate)} — {dateLabel(phase.dueDate)} · 负责人 {phase.owner}</span></div><span className={`pw-status status-${phase.status}`}>{statusLabel[phase.status]}</span><button className="pw-link-button" disabled={!canManage || busy} onClick={() => void updatePhase(phase, phase.status !== 'completed')}>{phase.status === 'completed' ? '重新打开' : '完成阶段'}</button></div><p>{phase.deliverables || '未填写交付物'}{phase.acceptanceCriteria ? ` · 验收：${phase.acceptanceCriteria}` : ''}</p><div className="pw-progress-track"><i style={{ width: `${phase.progress}%` }}/></div>{milestones.filter(item => item.phaseId === phase.id).map(item => <button className="pw-milestone-row" key={item.id} disabled={!canManage} onClick={() => void updateMilestone(item)}><Flag size={14}/><span>{item.title}</span><small>{dateLabel(item.dueDate)}</small><span className={`pw-status status-${item.status}`}>{statusLabel[item.status]}</span></button>)}</article>)}</div> : <Empty title="还没有阶段" detail="可以从模板生成阶段计划，也可以手动建立阶段、交付物与验收标准。" action={canManage && <button className="pw-button pw-button-primary" onClick={() => setModal('template')}><Plus size={14}/>模板建项</button>}/>}</section>
        <section className="pw-panel"><div className="pw-panel-heading"><div><span>PROJECT TASKS</span><h3>项目任务清单 <small>{projectTasks.length}</small></h3></div><div className="pw-panel-actions">{canManage && <label className="pw-button pw-button-secondary pw-upload-label"><Upload size={14}/>导入 CSV / Excel<input key={importInputKey} type="file" accept=".csv,.xlsx" onChange={event => void importPlan(event.target.files?.[0])} disabled={fileBusy}/></label>}<button className="pw-button pw-button-primary" onClick={() => setModal('task')}><Plus size={14}/>新建任务</button></div></div><div className="pw-export-row"><span>计划表</span><button onClick={() => void download(`/api/projects/${projectId}/export.csv`, `${selectedProject.code ?? 'project'}-plan.csv`)}><Download size={14}/>CSV</button><button onClick={() => void download(`/api/projects/${projectId}/export.xlsx`, `${selectedProject.code ?? 'project'}-plan.xlsx`)}><FileSpreadsheet size={14}/>Excel</button><small>导入时会按 WBS / 阶段 / 里程碑 / 任务字段校验。</small></div>{projectTasks.length ? <div className="pw-table-wrap"><table className="pw-table"><thead><tr><th>WBS / 任务</th><th>阶段</th><th>负责人</th><th>开始—截止</th><th>优先级</th><th>进度</th><th>状态</th></tr></thead><tbody>{projectTasks.map(task => <tr key={task.id}><td><div className="pw-task-title"><button type="button" className={`pw-task-check ${task.status === 'done' ? 'is-done' : ''}`} onClick={() => void toggleTask(task)} aria-label="切换任务状态">{task.status === 'done' ? <Check size={12}/> : <Circle size={13}/>}</button><div><b>{task.wbsCode ? `${task.wbsCode} ` : ''}{task.title}</b><small>{task.acceptanceCriteria || task.description || '—'}</small></div></div></td><td>{phases.find(item => item.id === task.phaseId)?.name ?? '—'}</td><td>{task.assignee || '—'}</td><td>{dateLabel(task.startDate)}<small className="pw-cell-sub">{dateLabel(task.dueDate)}</small></td><td><span className={`pw-priority priority-${task.priority}`}>{priorityLabel[task.priority]}</span></td><td><div className="pw-inline-progress"><i style={{ width: `${task.status === 'done' ? 100 : task.progress ?? 0}%` }}/></div><small>{task.status === 'done' ? 100 : task.progress ?? 0}%</small></td><td><span className={`pw-status status-${task.status}`}>{statusLabel[task.status]}</span></td></tr>)}</tbody></table></div> : <Empty title="暂无项目任务" detail="从模板建项可生成带 WBS 编码的计划任务；也可按阶段逐条添加。" action={<button className="pw-button pw-button-primary" onClick={() => setModal('task')}><Plus size={14}/>新建任务</button>}/>}</section></div>}

      {tab === 'gantt' && <section className="pw-panel pw-gantt-panel"><div className="pw-panel-heading"><div><span>PROJECT SCHEDULE</span><h3>项目甘特图</h3></div><small>{dateLabel(dayString(ganttTimeline.startDay))} — {dateLabel(dayString(ganttTimeline.endDay))} · {ganttItems.length} 项计划内容</small></div>{ganttItems.length ? <div className="pw-gantt-scroll"><div className="pw-gantt-board" style={{ width: `${260 + ganttTimeline.weekCount * 112}px` }}><div className="pw-gantt-axis" style={{ gridTemplateColumns: `260px ${ganttTimeline.weekCount * 112}px` }}><div className="pw-gantt-axis-label">阶段 / 工作项</div><div className="pw-gantt-axis-weeks" style={{ gridTemplateColumns: `repeat(${ganttTimeline.weekCount}, 112px)` }}>{ganttTimeline.weeks.map((day,index) => <span key={day}>{axisDateLabel(day)}<small>第 {index + 1} 周</small></span>)}</div></div>{ganttItems.map(item => { const start = dayNumber(item.startDate) ?? ganttTimeline.startDay; const end = Math.max(start, dayNumber(item.endDate) ?? start); const clippedStart = Math.max(ganttTimeline.startDay, Math.min(ganttTimeline.endDay, start)); const clippedEnd = Math.max(clippedStart, Math.min(ganttTimeline.endDay, end)); const left = ((clippedStart - ganttTimeline.startDay) / ganttTimeline.dayCount) * 100; const width = ((clippedEnd - clippedStart + 1) / ganttTimeline.dayCount) * 100; const markerLeft = ((clippedStart - ganttTimeline.startDay + .5) / ganttTimeline.dayCount) * 100; const complete = item.status === 'completed' || item.status === 'done'; const isOverdue = !complete && end < (dayNumber(today()) ?? 0); const progress = Math.max(0, Math.min(100, item.progress)); const kindLabel = item.kind === 'phase' ? '阶段' : item.kind === 'task' ? '任务' : item.kind === 'milestone' ? '里程碑' : '事件'; const todayPosition = ((dayNumber(today()) ?? 0) - ganttTimeline.startDay) / ganttTimeline.dayCount * 100; return <div className="pw-gantt-row" key={item.id} style={{ gridTemplateColumns: `260px ${ganttTimeline.weekCount * 112}px` }}><div className="pw-gantt-label"><span className={`pw-gantt-kind kind-${item.kind}`}>{kindLabel}</span><div><b title={item.title}>{item.title}</b><small>{item.detail} · {dateLabel(item.startDate)} — {dateLabel(item.endDate)}</small></div></div><div className="pw-gantt-track" style={{ width: `${ganttTimeline.weekCount * 112}px` }}>{ganttTimeline.weeks.map((week,index) => <i className="pw-gantt-gridline" key={week} style={{ left: `${index / ganttTimeline.weekCount * 100}%` }} />)}{todayPosition >= 0 && todayPosition <= 100 && <i className="pw-gantt-today" style={{ left: `${todayPosition}%` }} />}<div className={`pw-gantt-bar bar-${item.kind}${complete ? ' is-complete' : ''}${isOverdue ? ' is-overdue' : ''}`} style={{ left: item.kind === 'milestone' ? `${markerLeft}%` : `${left}%`, width: item.kind === 'milestone' ? 12 : `${width}%` }} title={`${item.title} · ${dateLabel(item.startDate)} — ${dateLabel(item.endDate)} · ${progress}%`}>
          {item.kind !== 'milestone' && <><i className="pw-gantt-bar-fill" style={{ width: `${progress}%` }} /><span>{progress > 0 ? `${progress}%` : ''}</span></>}
        </div></div></div> })}</div></div> : <Empty title="暂无可绘制的计划日期" detail="为阶段、任务、里程碑或事件设置计划开始与截止日期后，这里会自动生成时间轴。"/>}<div className="pw-gantt-legend"><span><i className="legend-phase"/>阶段</span><span><i className="legend-task"/>任务</span><span><i className="legend-milestone"/>里程碑</span><span><i className="legend-event"/>事件</span><span><i className="legend-today"/>今天</span></div></section>}
      {tab === 'events' && <div className="pw-events-layout"><section className="pw-panel"><div className="pw-panel-heading"><div><span>PROJECT EVENT REGISTER</span><h3>事件登记与闭环</h3></div><button className="pw-button pw-button-primary" onClick={() => setModal('event')}><Plus size={14}/>登记项目事件</button></div><div className="pw-notice"><ClipboardCheck size={16}/><span>每条事件均记录负责人、计划时间、权重与处理状态。标记完成后可启动 KPI 自评，再由不同主管完成复核。</span></div>{events.length ? <div className="pw-event-list">{events.map(item => {
          const review = eventReviews.find(r => r.eventId === item.id)
          return <article className="pw-event-card" key={item.id}><div className={`pw-event-icon event-${item.type}`}><ClipboardCheck size={17}/></div><div className="pw-event-main"><div className="pw-event-title"><span>{item.code}</span><b>{item.title}</b><span className="pw-event-type">{eventLabel[item.type]}</span></div><p>{item.description || '未补充事件说明。'}</p><div className="pw-event-meta"><span><Users size={13}/>{item.owner}</span><span><CalendarDays size={13}/>{dateLabel(item.startDate)} — {dateLabel(item.dueDate)}</span><span><Target size={13}/>{item.projectWeight}% 权重</span><span>{phases.find(phase => phase.id === item.phaseId)?.name ?? '未关联阶段'}</span></div>{review && <div className="pw-review-summary"><span className={`pw-status status-${review.status}`}>{statusLabel[review.status]}</span>{review.selfSubmittedAt && <small>自评 {review.selfScore.toFixed(1)}</small>}{review.status === 'approved' && <b>最终 {review.finalScore.toFixed(1)} 分</b>}{review.managerComment && <small>主管意见：{review.managerComment}</small>}</div>}</div><div className="pw-event-actions"><span className={`pw-status status-${item.status}`}>{statusLabel[item.status]}</span><button className="pw-link-button" disabled={busy} onClick={() => void completeEvent(item)}>{item.status === 'completed' ? '重新打开' : '标记完成'}</button>{item.status === 'completed' && !review && currentUser.role !== 'member' && <button className="pw-link-button" disabled={busy} onClick={() => void startReview(item)}>发起绩效评审</button>}{review?.status === 'self-review' && (currentUser.id === item.ownerId || currentUser.role !== 'member') && <button className="pw-link-button" onClick={() => { setReviewId(review.id); setModal('self-review') }}>填写自评</button>}{review?.status === 'manager-review' && currentUser.role !== 'member' && <button className="pw-link-button" disabled={review.selfReviewerId === currentUser.id} onClick={() => { setReviewId(review.id); setModal('manager-review') }}>{review.selfReviewerId === currentUser.id ? '需由其他主管评审' : '主管评审'}</button>}</div></article>
        })}</div> : <Empty title="还没有项目事件" detail="会议、决策、风险、问题、变更和交付物都可以登记为事件，后续可关联绩效评审。" action={<button className="pw-button pw-button-primary" onClick={() => setModal('event')}><Plus size={14}/>登记首条事件</button>}/>}</section>
        <aside className="pw-panel pw-weight-panel"><div className="pw-panel-heading"><div><span>EVENT WEIGHT</span><h3>项目事件绩效分布</h3></div><BarChart3 size={17}/></div><p>事件权重用于项目贡献汇总；KPI 核定规则的生效权重必须另行合计为 100%。</p>{events.map(item => <div className="pw-weight-line" key={item.id}><span title={item.title}>{item.title}</span><div><i style={{ width: `${Math.min(100,item.projectWeight)}%` }}/></div><b>{item.projectWeight}%</b></div>)}{!events.length && <small>登记事件后显示贡献权重。</small>}</aside></div>}

      {tab === 'reports' && <div className="pw-report-layout"><section className="pw-panel"><div className="pw-panel-heading"><div><span>PROJECT STATUS REPORT</span><h3>项目进展汇报</h3></div><button className="pw-button pw-button-primary" onClick={() => setModal('report')}><Plus size={14}/>新建汇报</button></div><div className="pw-report-kpis"><div><span>报告周期</span><b>{reports[0]?.period ?? monthLabel()}</b></div><div><span>当前进度</span><b>{completion}%</b></div><div><span>未关闭风险/问题</span><b>{events.filter(item => ['risk','issue'].includes(item.type) && !['completed','cancelled'].includes(item.status)).length}</b></div><div><span>近期里程碑</span><b>{nextMilestones}</b></div></div>{reports.length ? <div className="pw-report-list">{reports.map(report => <article className="pw-report-card" key={report.id}><div className="pw-report-head"><div><span>{report.period}</span><b>进度 {report.progress}%</b></div><small>{report.author} · {report.createdAt ? dateLabel(report.createdAt.slice(0,10)) : '—'}</small></div><div className="pw-report-grid"><div><b>本期成果</b><p>{report.achievements || '—'}</p></div><div><b>阻塞项</b><p>{report.blockers || '—'}</p></div><div><b>风险</b><p>{report.risks || '—'}</p></div><div><b>需决策事项</b><p>{report.decisionsNeeded || '—'}</p></div><div className="pw-report-wide"><b>下一步</b><p>{report.nextSteps || '—'}</p></div></div></article>)}</div> : <Empty title="还没有项目汇报" detail="记录成果、阻塞、风险、需要决策的事项与下一步，形成可追溯的状态报告。" action={<button className="pw-button pw-button-primary" onClick={() => setModal('report')}><Plus size={14}/>新建首份汇报</button>}/>}</section><aside className="pw-panel pw-report-guide"><div className="pw-panel-heading"><div><span>REPORTING CHECKLIST</span><h3>汇报要点</h3></div><FileText size={17}/></div><p>项目汇报结构按常见项目状态报告实践设置，可按企业制度补充字段。</p><ul><li>实际进度与计划偏差</li><li>本期交付物与成果证据</li><li>阻塞问题、风险和应对责任</li><li>需要管理层决策的事项</li><li>下一周期行动与负责人</li></ul></aside></div>}

      {tab === 'files' && <div className="pw-file-layout"><section className="pw-panel"><div className="pw-panel-heading"><div><span>PROJECT DOCUMENT CONTROL</span><h3>项目图文档与附件</h3></div><button className="pw-button pw-button-secondary" disabled={fileBusy} onClick={() => void refreshFiles()}><RefreshCw size={14}/>刷新</button></div><div className="pw-file-toolbar"><form className="pw-upload-form" onSubmit={uploadProjectFile}><label className="pw-button pw-button-primary pw-file-pick"><Upload size={14}/>{fileBusy ? '上传中…' : '上传附件'}<input type="file" name="file" required disabled={fileBusy}/></label><input className="pw-file-title" name="title" placeholder="文件说明（可选）" maxLength={160}/><button type="submit" className="pw-button pw-button-secondary" disabled={fileBusy}>保存附件</button></form><button className="pw-button pw-button-secondary" onClick={() => void download(`/api/projects/${projectId}/archive.zip`, `${selectedProject.code ?? 'project'}-archive.zip`)}><FileArchive size={14}/>下载项目归档包</button></div><p className="pw-file-note">上传文件按当前租户 / 组织 / 账套和项目隔离。归档包包含项目概要、阶段、任务、事件、评审、汇报及附件清单；不包含其他项目或账套数据。</p>{files.length ? <div className="pw-file-list">{files.map(file => <div className="pw-file-row" key={file.id}><div className="pw-file-icon"><Paperclip size={16}/></div><div className="pw-file-info"><b>{file.name}</b><small>{fileSize(file.size)} · {file.uploadedBy} · {dateLabel(file.createdAt.slice(0,10))}</small></div><button className="pw-icon-button" aria-label={`下载 ${file.name}`} title="下载" onClick={() => void download(`/api/projects/${projectId}/files/${encodeURIComponent(file.id)}/content`, file.name)}><Download size={16}/></button>{canManage && <button className="pw-icon-button pw-delete-file" aria-label={`删除 ${file.name}`} title="删除附件" onClick={() => { if (window.confirm(`确定删除附件“${file.name}”吗？此操作不可撤销。`)) void run(() => apiJson(`/api/projects/${projectId}/files/${encodeURIComponent(file.id)}`, { method: 'DELETE' }).then(() => refreshFiles()), '附件已删除') }}><X size={15}/></button>}</div>)}</div> : <Empty title="项目附件为空" detail="上传项目章程、验证记录、会议纪要、图纸或其他交付证据。"/>}</section>
        <aside className="pw-panel"><div className="pw-panel-heading"><div><span>PLAN EXCHANGE</span><h3>计划表导入 / 导出</h3></div><FileSpreadsheet size={17}/></div><p>Excel 工作簿按「项目概要、阶段与里程碑、任务、事件与绩效、汇报」分表；CSV 面向任务计划数据交换。</p><div className="pw-export-stack"><button onClick={() => void download(`/api/projects/${projectId}/export.xlsx`, `${selectedProject.code ?? 'project'}-workspace.xlsx`)}><FileSpreadsheet size={16}/>导出 Excel 工作簿<ArrowRight size={14}/></button><button onClick={() => void download(`/api/projects/${projectId}/export.csv`, `${selectedProject.code ?? 'project'}-tasks.csv`)}><Download size={16}/>导出任务 CSV<ArrowRight size={14}/></button>{canManage && <label className="pw-import-button"><Upload size={16}/>导入 CSV / Excel<input key={importInputKey} type="file" accept=".csv,.xlsx" onChange={event => void importPlan(event.target.files?.[0])} disabled={fileBusy}/></label>}</div><small className="pw-muted">导入前会做字段和日期校验；仅当前项目写入。</small></aside></div>}
    </>}
    {error && <div className="pw-error" role="status"><AlertTriangle size={15}/>{error}<button onClick={() => setError('')} aria-label="关闭错误"><X size={14}/></button></div>}

    <AnimatePresence>
      {modal === 'template' && <WorkModal title="用模板创建项目" onClose={() => setModal(null)} wide><form className="pw-form-grid" onSubmit={createFromTemplate}>
        <Field label="项目模板"><select name="templateId" value={templateId} onChange={event => setTemplateId(event.target.value)}>{templates.map(template => <option key={template.id} value={template.id}>{template.name} · {template.type}</option>)}</select></Field><Field label="项目名称"><input name="name" required autoFocus maxLength={120} placeholder="例如：智能设备新产品开发"/></Field><Field label="项目类型"><input name="type" defaultValue={templates.find(item => item.id === templateId)?.type ?? '产品开发'} maxLength={80}/></Field><Field label="所属部门"><input name="department" placeholder="例如：研发中心" maxLength={120}/></Field><Field label="负责人"><select name="ownerId" defaultValue={currentUser.id} onChange={event => { const user = users.find(item => item.id === event.target.value); const input = document.querySelector<HTMLInputElement>('[name="owner"]'); if (input && user) input.value = user.displayName }}><option value={currentUser.id}>{currentUser.displayName}（我）</option>{(canManage ? users.filter(user => user.id !== currentUser.id) : []).map(user => <option key={user.id} value={user.id}>{user.displayName} · {user.email}</option>)}</select><input name="owner" hidden defaultValue={currentUser.displayName}/></Field><Field label="发起 / 赞助人"><input name="sponsor" placeholder="项目发起人" maxLength={120}/></Field><Field label="计划开始"><input type="date" name="startDate" defaultValue={today()} required/></Field><Field label="计划完成"><input type="date" name="dueDate"/></Field><Field label="优先级"><select name="priority" defaultValue="medium"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></Field><Field label="项目目标" wide><textarea name="goal" rows={2} placeholder="说明要达成的业务结果" maxLength={4000}/></Field><Field label="范围边界" wide><textarea name="scope" rows={2} placeholder="明确包含与不包含的范围" maxLength={4000}/></Field><Field label="成功标准" wide><textarea name="successCriteria" rows={2} placeholder="量化定义验收门槛" maxLength={4000}/></Field><Field label="项目简介" wide><textarea name="description" rows={2} placeholder={templates.find(item => item.id === templateId)?.description} maxLength={2000}/></Field><div className="pw-template-preview pw-field-wide"><b>模板预览</b><div>{(templates.find(item => item.id === templateId)?.phases ?? []).map((phase,index) => <span key={phase.name}>{index+1}. {phase.name} · {phase.milestones.length} 里程碑 · {phase.tasks.length} 任务</span>)}</div></div><div className="pw-form-actions pw-field-wide"><button type="button" className="pw-button pw-button-secondary" onClick={() => setModal(null)}>取消</button><button type="submit" className="pw-button pw-button-primary" disabled={busy}>{busy ? '创建中…' : <><Plus size={14}/>创建项目及阶段计划</>}</button></div></form></WorkModal>}
      {modal === 'phase' && <WorkModal title="新增项目阶段" onClose={() => setModal(null)}><form className="pw-form-grid" onSubmit={createPhase}><Field label="阶段名称"><input name="name" required autoFocus maxLength={120} placeholder="例如：方案设计与评审"/></Field><Field label="阶段编码"><input name="code" defaultValue={`P${phases.length+1}`} maxLength={30}/></Field><Field label="计划开始"><input type="date" name="startDate" defaultValue={today()} required/></Field><Field label="计划结束"><input type="date" name="dueDate" defaultValue={addDays(today(),7)} required/></Field><Field label="负责人"><input name="owner" defaultValue={selectedProject?.owner ?? currentUser.displayName} required/></Field><Field label="关键交付物" wide><textarea name="deliverables" rows={2} maxLength={2000}/></Field><Field label="验收标准" wide><textarea name="acceptanceCriteria" rows={2} maxLength={2000}/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="保存阶段"/></form></WorkModal>}
      {modal === 'milestone' && <WorkModal title="新增里程碑" onClose={() => setModal(null)}><form className="pw-form-grid" onSubmit={createMilestone}><Field label="里程碑名称"><input name="title" required autoFocus maxLength={160} placeholder="例如：设计评审通过"/></Field><Field label="里程碑编码"><input name="code" defaultValue={`M${milestones.length+1}`} maxLength={30}/></Field><Field label="所属阶段"><select name="phaseId"><option value="">未关联阶段</option>{phases.map(phase => <option key={phase.id} value={phase.id}>{phase.code} · {phase.name}</option>)}</select></Field><Field label="计划日期"><input type="date" name="dueDate" defaultValue={addDays(today(),7)} required/></Field><Field label="负责人"><input name="owner" defaultValue={selectedProject?.owner ?? currentUser.displayName} required/></Field><Field label="验收标准" wide><textarea name="acceptanceCriteria" required rows={3} maxLength={2000}/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="保存里程碑"/></form></WorkModal>}
      {modal === 'task' && <WorkModal title="创建项目任务" onClose={() => setModal(null)}><form className="pw-form-grid" onSubmit={createTask}><Field label="任务名称"><input name="title" required autoFocus maxLength={160} placeholder="清晰描述下一步行动"/></Field><Field label="WBS 编码"><input name="wbsCode" defaultValue={`${phases.length || 1}.${projectTasks.length+1}`} maxLength={40}/></Field><Field label="所属阶段"><select name="phaseId"><option value="">未关联阶段</option>{phases.map(phase => <option key={phase.id} value={phase.id}>{phase.code} · {phase.name}</option>)}</select></Field><Field label="关联里程碑"><select name="milestoneId"><option value="">无</option>{milestones.map(item => <option key={item.id} value={item.id}>{item.code} · {item.title}</option>)}</select></Field><Field label="计划开始"><input type="date" name="startDate" defaultValue={today()} required/></Field><Field label="计划截止"><input type="date" name="dueDate" defaultValue={addDays(today(),7)} required/></Field><Field label="优先级"><select name="priority" defaultValue="medium"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></Field><Field label="预计工时"><input type="number" name="estimateHours" min="0" step="0.5" defaultValue="0"/></Field><Field label="负责人"><select name="assigneeId" defaultValue={currentUser.id} onChange={event => { const user=users.find(item=>item.id===event.target.value); const input=document.querySelector<HTMLInputElement>('[name="assignee"]'); if(input&&user) input.value=user.displayName }}><option value={currentUser.id}>{currentUser.displayName}（我）</option>{(canManage?users.filter(user=>user.id!==currentUser.id):[]).map(user=><option key={user.id} value={user.id}>{user.displayName} · {user.email}</option>)}</select><input name="assignee" hidden defaultValue={currentUser.displayName}/></Field><Field label="验收标准" wide><textarea name="acceptanceCriteria" rows={3} maxLength={2000} placeholder="完成的判定条件"/></Field><Field label="任务说明" wide><textarea name="description" rows={2} maxLength={2000}/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="创建任务"/></form></WorkModal>}
      {modal === 'event' && <WorkModal title="登记项目事件" onClose={() => setModal(null)} wide><form className="pw-form-grid" onSubmit={createEvent}><Field label="事件标题"><input name="title" required autoFocus maxLength={160} placeholder="例如：样机性能验证完成"/></Field><Field label="事件编号"><input name="code" defaultValue={`EVT-${String(events.length+1).padStart(3,'0')}`} maxLength={40}/></Field><Field label="事件类型"><select name="type" defaultValue="deliverable">{Object.entries(eventLabel).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="关联阶段"><select name="phaseId"><option value="">未关联</option>{phases.map(phase=><option key={phase.id} value={phase.id}>{phase.name}</option>)}</select></Field><Field label="关联任务"><select name="taskId"><option value="">未关联</option>{projectTasks.map(task=><option key={task.id} value={task.id}>{task.wbsCode} {task.title}</option>)}</select></Field><Field label="事件负责人"><select name="ownerId" defaultValue={currentUser.id} onChange={event=>{const user=users.find(item=>item.id===event.target.value);const input=document.querySelector<HTMLInputElement>('[name="owner"]');if(input&&user)input.value=user.displayName}}><option value={currentUser.id}>{currentUser.displayName}（我）</option>{(canManage?users.filter(user=>user.id!==currentUser.id):[]).map(user=><option key={user.id} value={user.id}>{user.displayName} · {user.email}</option>)}</select><input name="owner" hidden defaultValue={currentUser.displayName}/></Field><Field label="所属部门"><input name="department" defaultValue={selectedProject?.department ?? ''} maxLength={120}/></Field><Field label="事件权重 %"><input type="number" name="projectWeight" min="0" max="100" step="0.1" defaultValue="10" required/></Field><Field label="计划开始"><input type="date" name="startDate" defaultValue={today()} required/></Field><Field label="计划完成"><input type="date" name="dueDate" defaultValue={addDays(today(),7)} required/></Field><Field label="事件描述 / 验收依据" wide><textarea name="description" rows={3} maxLength={4000} placeholder="记录背景、交付结果、证据链接或验收依据"/></Field><div className="pw-form-actions pw-field-wide"><button type="button" className="pw-button pw-button-secondary" onClick={() => setModal(null)}>取消</button><button type="submit" className="pw-button pw-button-primary" disabled={busy}>{busy ? '保存中…' : <><Plus size={14}/>保存事件</>}</button></div></form></WorkModal>}
      {modal === 'report' && <WorkModal title="新增项目进展汇报" onClose={() => setModal(null)} wide><form className="pw-form-grid" onSubmit={createReport}><Field label="汇报周期"><input name="period" defaultValue={monthLabel()} required placeholder="例如：2026-W42 / 2026-10" maxLength={40}/></Field><Field label="报告进度 %"><input type="number" name="progress" min="0" max="100" defaultValue={completion} required/></Field><Field label="本期成果" wide><textarea name="achievements" rows={2} maxLength={4000}/></Field><Field label="阻塞项" wide><textarea name="blockers" rows={2} maxLength={4000}/></Field><Field label="风险及应对" wide><textarea name="risks" rows={2} maxLength={4000}/></Field><Field label="需要的决策 / 支持" wide><textarea name="decisionsNeeded" rows={2} maxLength={4000}/></Field><Field label="下一周期计划" wide><textarea name="nextSteps" rows={2} maxLength={4000}/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="保存汇报"/></form></WorkModal>}
      {modal === 'self-review' && currentReview && <WorkModal title={`事件自评 · ${events.find(item=>item.id===currentReview.eventId)?.title ?? ''}`} onClose={() => setModal(null)} wide><form className="pw-form-grid" onSubmit={submitSelfReview}><div className="pw-review-intro pw-field-wide"><b>按已生效 KPI 规则填写实际值</b><span>规则快照在启动评审时锁定；计算分数由服务器完成。当前事件权重 {currentReview.eventWeight}%。</span></div>{currentReview.rulesSnapshot.map(rule=><ReactRuleInput key={rule.kpiRuleId} rule={rule} mode="self"/>)}<Field label="自评意见" wide><textarea name="comment" required rows={3} maxLength={4000} placeholder="说明完成情况、偏差原因与改进点"/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="提交自评"/></form></WorkModal>}
      {modal === 'manager-review' && currentReview && <WorkModal title={`主管评审 · ${events.find(item=>item.id===currentReview.eventId)?.title ?? ''}`} onClose={() => setModal(null)} wide><form className="pw-form-grid" onSubmit={submitManagerReview}><div className="pw-review-intro pw-field-wide"><b>独立复核自评记录</b><span>自评人：{currentReview.employee} · 自评总分 {currentReview.selfScore.toFixed(1)}；主管评审人与自评人必须为不同人员。</span></div>{currentReview.rulesSnapshot.map(rule=><ReactRuleInput key={rule.kpiRuleId} rule={rule} mode="manager" selfLine={currentReview.selfScores.find(line=>line.kpiRuleId===rule.kpiRuleId)}/>)}<Field label="主管评审意见" wide><textarea name="comment" required rows={3} maxLength={4000} placeholder="评审结论、依据与必要的改进建议"/></Field><FormActions busy={busy} onCancel={() => setModal(null)} submit="完成主管评审"/></form></WorkModal>}
    </AnimatePresence>
  </section>
}

function ReactRuleInput({ rule, mode, selfLine }: { rule: ProjectEventReview['rulesSnapshot'][number]; mode: 'self' | 'manager'; selfLine?: EventScoreLine }) {
  return <div className="pw-rule-input pw-field-wide"><div><b>{rule.code} · {rule.name}</b><small>{rule.formula} · 目标 {rule.target} {rule.unit} · 权重 {rule.weight}%</small></div><label><span>{mode === 'self' ? '实际值' : '主管评分'}</span><input name={mode === 'self' ? `actual-${rule.kpiRuleId}` : `score-${rule.kpiRuleId}`} type="number" step="0.01" min="0" max={mode === 'self' ? undefined : 120} required defaultValue={mode === 'self' ? '' : selfLine?.score}/></label>{mode === 'manager' && <label><span>复核实际值</span><input name={`actual-${rule.kpiRuleId}`} type="number" step="0.01" min="0" defaultValue={selfLine?.actual ?? 0}/></label>}<label className="pw-rule-comment"><span>说明（可选）</span><input name={`comment-${rule.kpiRuleId}`} maxLength={1000} placeholder="说明得分依据或偏差"/></label>{mode === 'manager' && selfLine && <small className="pw-self-score">自评：实际值 {selfLine.actual} · {selfLine.score.toFixed(1)} 分</small>}</div>
}
function FormActions({ busy, onCancel, submit }: { busy: boolean; onCancel: () => void; submit: string }) { return <div className="pw-form-actions pw-field-wide"><button type="button" className="pw-button pw-button-secondary" onClick={onCancel}>取消</button><button type="submit" className="pw-button pw-button-primary" disabled={busy}>{busy ? '处理中…' : submit}</button></div> }
